camera: Optional[Picamera2] = None


def initialize_camera() -> Picamera2:
    """Initializes the Picamera2 camera with error handling."""
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)})
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        logger.error(f"Camera initialization failed: {e}")
        raise  # Re-raise the exception to be handled by the caller


def detect_object(picam2: Picamera2, classifier: str) -> Tuple[bytes, bool]:
    """Detects objects in a frame using the provided classifier."""
    try:
        frame = picam2.capture_array()
        # Placeholder for actual object detection logic using the classifier
        detected = False  # Replace with actual detection result
        # Example (replace with your detection logic):
        # if classifier == 'motion_detector':
        #     detected = detect_motion(frame)  # Implement detect_motion()
        # elif classifier == 'face_detector':
        #     detected = detect_face(frame)  # Implement detect_face()
        else:
            detected = False

        _, jpeg = picam2.capture_multipart(["jpeg"])
        return jpeg, detected

    except Exception as e:
        logger.error(f"Error during object detection: {e}")
        return b"", False



def check_for_objects():
    """Continuously checks for objects and sends email notifications if configured."""
    while True:
        try:
            if Config.send_email_notifications:
                if Config.classifier_name == 'motion_detector':
                    image, detected = detect_object(camera, 'motion_detector')  # Replace with actual motion detection
                else:
                    image, detected = detect_object(camera, Config.classifier_name)

                if detected:
                    logger.info("Object detected!")
                    if (time.time() - Config.last_epoch) > Config.email_send_interval:
                        Config.last_epoch = time.time()
                        try:
                            send_email(image, Config)
                            logger.info("Email sent successfully.")
                        except Exception as e:
                            logger.error(f"Error sending email: {e}")
            else:
                time.sleep(2)  # Reduced sleep time when emails are off

        except Exception as e:
            logger.error(f"Error in object detection loop: {e}")
            time.sleep(5)  # Prevent excessive logging on repeated errors



def start_object_detection_thread():
    """Starts the object detection thread."""
    thread = threading.Thread(target=check_for_objects, daemon=True)
    thread.name = "ObjectDetectionThread"
    thread.start() + logger.info(f"Object detection thread '{thread.name}' started.")


