    def index() -> str:
        """Handles the main web page."""
        if request.method == 'POST':
            try:
                Config.live_preview = 'live_preview' in request.form
                Config.classifier_name = request.form.get('classifier', '')
                Config.send_email_notifications = 'send_email_notifications' in request.form
                Config.receiver_email_address = request.form.get('receiver_email_address', '')
                Config.email_send_interval = int(request.form.get('email_send_interval', 0))
                Config.camera_wake_up = 'camera_wake_up' in request.form

                if Config.classifier_name not in ('motion_detector', 'face_detector'):  # Example classifiers
                    logger.warning(f"Invalid classifier: {Config.classifier_name}. Defaulting to 'motion'.")
                    Config.classifier_name = 'motion'  # Default classifier

            except Exception as e:
                logger.error(f"Error processing form data: {e}")

        return render_template('index.html', classifiers=['motion_detector', 'face_detector'], config=Config)  # Pass classifiers


    @app.route('/video_feed')  # Simplified route name
    def video_feed() -> Response:
        """Streams the video feed."""
        def generate():
            while True:
                try:
                    frame = camera.capture_array()  # Capture frame as numpy array
                    # Placeholder for object detection (optional)
                    # detected = detect_object(frame, Config.classifier_name) # Example
                    _, jpeg = camera.capture_multipart(["jpeg"])
                    yield (b'--frame\r\n'
                           b'Content-Type: image/jpeg\r\n\r\n' + jpeg + b'\r\n\r\n')
                except Exception as e:
                    logger.error(f"Error generating video feed: {e}")
                    yield b"Error generating video feed"  # Send error message to client
                    break # Stop generating frames after an error

        return Response(generate(), mimetype='multipart/x-mixed-replace; boundary=frame')


    return app


def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logger.info('Shutting down app...')
    if camera:
        try:
            camera.stop()
            camera.close()
            logger.info("Camera stopped and closed.")
        except Exception as e:
            logger.error(f"Error closing camera: {e}")
    sys.exit(0)


def main():
    """Main function to start the application."""
    global camera

    try:
        camera = initialize_camera()
    except Exception as e:
        logger.critical(f"Failed to initialize camera. Exiting. {e}")
        sys.exit(1)


    start_object_detection_thread()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    app = create_app()
    app.run(host='0.0.0.0', debug=False, threaded=True)


if __name__ == '__main__':
    main()

