import RPi.GPIO as GPIO
import time
import speech_recognition as sr
import os
import datetime
import signal
import sys
import random
try:
    import picamera2
    camera_available = True
except ImportError:
    camera_available = False
    print("picamera2 not found, camera functionality will be simulated.")
try:
    import adafruit_dht
    dht_available = True
except ImportError:
    dht_available = False
    print("adafruit_dht not found, temperature sensor functionality will be simulated.")

# GPIO pin definitions
LIGHT_PIN = 17
DHT_PIN = 4

# Global variables
lights_on = False
temperature = 25.0  # Default temperature

# Function to handle program exit gracefully
def signal_handler(sig, frame):
    print('You pressed Ctrl+C!')
    GPIO.cleanup()
    sys.exit(0)

# Register the signal handler
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Initialize GPIO
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHT_PIN, GPIO.OUT)
    print("GPIO initialized successfully.")
except Exception as e:
    print(f"Error initializing GPIO: {e}. Running in simulation mode.")
    GPIO = None  # Disable GPIO if initialization fails

def turn_lights_on():
    """Turns the lights on by setting the GPIO pin HIGH."""
    global lights_on
    if GPIO:
        GPIO.output(LIGHT_PIN, GPIO.HIGH)
        lights_on = True
        print("Lights turned ON.")
    else:
        print("Lights turned ON (simulated).")

def turn_lights_off():
    """Turns the lights off by setting the GPIO pin LOW."""
    global lights_on
    if GPIO:
        GPIO.output(LIGHT_PIN, GPIO.LOW)
        lights_on = False
        print("Lights turned OFF.")
    else:
        print("Lights turned OFF (simulated).")

def read_temperature():
    """Reads the temperature from the DHT11 sensor."""
    global temperature
    if dht_available:
        try:
            dht_device = adafruit_dht.DHT11(DHT_PIN)
            temperature = dht_device.temperature
            if temperature is not None:
                print(f"Temperature: {temperature:.1f} °C")
            else:
                print("Failed to read temperature from DHT11 sensor.")
                temperature = get_simulated_temperature() # Fallback to simulation
        except Exception as e:
            print(f"Error reading temperature: {e}")
            temperature = get_simulated_temperature() # Fallback to simulation
    else:
        temperature = get_simulated_temperature()
        print(f"Temperature: {temperature:.1f} °C (simulated)")

def get_simulated_temperature():
    """Returns a simulated temperature value."""
    return random.uniform(15, 35)

def capture_image():
    """Captures an image using the Raspberry Pi camera."""
    if camera_available:
        try:
            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            picam2 = picamera2.PiCamera2()
            picam2.configure(picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
            picam2.start()
            time.sleep(2)  # Allow camera to warm up
            picam2.capture_file(filename)
            picam2.close()
            print(f"Image captured: {filename}")
        except Exception as e:
            print(f"Error capturing image: {e}")
    else:
        print("Camera not available, simulating image capture.")
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        print(f"Simulated image capture: {filename}")

def process_voice_command(command):
    """Processes the voice command and performs the corresponding action."""
    command = command.lower()
    if "turn on the lights" in command:
        turn_lights_on()
    elif "turn off the lights" in command:
        turn_lights_off()
    elif "what is the temperature" in command:
        read_temperature()
    elif "take a picture" in command:
        capture_image()
    else:
        print("Unknown command.")

def main():
    """Main function to run the voice-controlled greenhouse system."""
    r = sr.Recognizer()
    mic = sr.Microphone()

    with mic as source:
        print("Calibrating microphone...")
        r.adjust_for_ambient_noise(source)  # Adjust for background noise
        print("Ready for voice commands. Say 'Greenhouse' to start.")

    while True:
        try:
            with mic as source:
                print("Listening...")
                audio = r.listen(source, timeout=5) # Listen for up to 5 seconds

            try:
                voice_data = r.recognize_google(audio)
                print(f"You said: {voice_data}")

                if "greenhouse" in voice_data.lower():
                    command = voice_data.lower().replace("greenhouse", "").strip()
                    process_voice_command(command)

            except sr.UnknownValueError:
                print("Could not understand audio")
            except sr.RequestError as e:
                print(f"Could not request results from Google Speech Recognition service; {e}")
            except sr.WaitTimeoutError:
                print("No speech detected within the timeout period.")

        except KeyboardInterrupt:
            print("Exiting program.")
            break
        except Exception as e:
            print(f"An unexpected error occurred: {e}")

    if GPIO:
        GPIO.cleanup()  # Clean up GPIO on exit

if __name__ == "__main__":
    main()

