import RPi.GPIO as GPIO
import time
import signal
import sys

# Define GPIO pins using BCM numbering
GPIO_PINS = {
    "inputs": [4, 5, 6],
    "outputs": [23, 24]
}

# Define pin roles
PIN_CONFIG = {
    4: "input",
    5: "input",
    6: "input",
    23: "output",
    24: "output"
}

# Initialize GPIO state
GPIO_STATE = {
    4: False,
    5: False,
    6: False,
    23: False,
    24: False
}


def setup_gpio():
    """Set up GPIO pins based on their configured roles."""
    try:
        GPIO.setmode(GPIO.BCM)  # Use BCM pin numbering
        for pin, role in PIN_CONFIG.items():
            GPIO.setup(pin, GPIO.IN if role == "input" else GPIO.OUT)
            GPIO.output(pin, GPIO.LOW)  # Initialize outputs to LOW
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        sys.exit(1)


def read_inputs():
    """Read the state of input pins and update GPIO_STATE."""
    for pin in GPIO_PINS["inputs"]:
        try:
            GPIO_STATE[pin] = bool(GPIO.input(pin))
        except Exception as e:
            print(f"Error reading input on pin {pin}: {e}")
            GPIO_STATE[pin] = False  # Assume LOW on error


def control_outputs():
    """Control output pins based on input states and logic."""
    try:
        if GPIO_STATE[4]:  # If input 4 is HIGH
            GPIO.output(23, GPIO.HIGH)  # Set output 23 HIGH
        elif GPIO_STATE[5]:  # If input 5 is HIGH (and input 4 is not)
            GPIO.output(23, GPIO.LOW)  # Set output 23 LOW

        if GPIO_STATE[6]:  # If input 6 is HIGH
            GPIO_STATE[24] = not GPIO_STATE[24]  # Toggle internal state
            GPIO.output(24, GPIO.HIGH if GPIO_STATE[24] else GPIO.LOW)

    except Exception as e:
        print(f"Error controlling outputs: {e}")


def main_loop():
    """Main control loop."""
    try:
        while True:
            read_inputs()
            control_outputs()
            time.sleep(0.05)  # Short delay
    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit


if __name__ == "__main__":
    setup_gpio()
    main_loop()

