            GPIO_STATE[pin] = bool(GPIO.input(pin))
        except Exception as e:
            print(f"Error reading input on pin {pin}: {e}")
            GPIO_STATE[pin] = False  # Assume LOW on error


def control_outputs():
    """Control output pins based on input states and logic."""
    try:
