            GPIO.output(23, GPIO.HIGH)  # Set output 23 HIGH
        elif GPIO_STATE[5]:  # If input 5 is HIGH (and input 4 is not)
            GPIO.output(23, GPIO.LOW)  # Set output 23 LOW

        if GPIO_STATE[6]:  # If input 6 is HIGH
            GPIO_STATE[24] = not GPIO_STATE[24]  # Toggle internal state
            GPIO.output(24, GPIO.HIGH if GPIO_STATE[24] else GPIO.LOW)

    except Exception as e:
        print(f"Error controlling outputs: {e}")


def main_loop():
    """Main control loop."""
    try:
        while True:
            read_inputs()
            control_outputs()
            time.sleep(0.05)  # Short delay
    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit


if __name__ == "__main__":
    setup_gpio()
    main_loop()

