import logging

# Configure logging to file for error tracking
logging.basicConfig(filename='error_log.txt', level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')

def initialize_camera(camera_index=0):
    """Initializes the USB camera at the given index."""
    try:
        cap = cv2.VideoCapture(camera_index)
        if not cap.isOpened():
            raise Exception("Could not open camera")
        return cap
    except Exception as e:
        logging.error(f"Camera initialization failed: {e}")
        return None

def capture_frame(cap):
    """Captures a frame from the camera and converts it to grayscale."""
    try:
        ret, frame = cap.read()
        if not ret:
            raise Exception("Failed to capture frame")
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        return gray
    except Exception as e:
        logging.error(f"Frame capture failed: {e}")
        return None

def decode_qr_code(image):
    """Decodes QR codes from the given image using pyzbar."""
    try:
        decoded_objects = decode(image)
        return decoded_objects
    except Exception as e:
        logging.error(f"QR code decoding failed: {e}")
        return []

def validate_item_id(item_id):
    """Validates the item_id to ensure it is alphanumeric."""
    if item_id.isalnum():
        return True
    else:
        logging.warning(f"Invalid item_id: {item_id}")
        return False

def log_inventory_data(camera_id, item_id, capture_time, log_file='inventory_log.csv'):
    """Logs the inventory data to a CSV file."""
    try:
        file_exists = os.path.isfile(log_file)
        with open(log_file, 'a', newline='') as csvfile:
            fieldnames = ['camera_id', 'item_id', 'capture_time']
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
            if not file_exists:
                writer.writeheader()
            writer.writerow({'camera_id': camera_id, 'item_id': item_id, 'capture_time': capture_time})
    except Exception as e:
        logging.error(f"File I/O error: {e}")

