    """Main function to run the QR code inventory system."""
    camera_id = "Camera 1"
    cap = initialize_camera()

    if cap is None:
        print("Exiting due to camera initialization failure.")
        return

    try:
        while True:
            frame = capture_frame(cap)
            if frame is None:
                time.sleep(0.2)
                continue

            decoded_objects = decode_qr_code(frame)

            for obj in decoded_objects:
                item_id = obj.data.decode('utf-8')
                if validate_item_id(item_id):
                    capture_time = datetime.datetime.now().isoformat()
                    log_inventory_data(camera_id, item_id, capture_time)
                    print(f"Item ID: {item_id}, Captured at: {capture_time}")

            time.sleep(0.2)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        cap.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

