import RPi.GPIO as GPIO
import time
from functools import partial

# Constants
GPIO_MODE = GPIO.BOARD
TRIGGER_PIN = 8
ECHO_PIN = 18
SOUND_SPEED = 34300
TIMEOUT = 0.02  # Timeout for echo pulse in seconds
MIN_DISTANCE = 2
MAX_DISTANCE = 400

def setup_gpio(trigger_pin, echo_pin, mode=GPIO_MODE):
    """Sets up the GPIO pins for ultrasonic sensor."""
    try:
        GPIO.setmode(mode)
        GPIO.setup(trigger_pin, GPIO.OUT)
        GPIO.setup(echo_pin, GPIO.IN)
        GPIO.output(trigger_pin, False)
        time.sleep(0.1)  # Sensor settling time
    except Exception as e:
        raise RuntimeError(f"GPIO setup failed: {e}")


def measure_distance(trigger_pin, echo_pin, timeout=TIMEOUT):
    """Measures the distance using the ultrasonic sensor."""
    try:
        GPIO.output(trigger_pin, True)
        time.sleep(0.00001)
        GPIO.output(trigger_pin, False)

        get_time = time.time  # Optimization: local reference

        pulse_start = wait_for_edge(echo_pin, GPIO.HIGH, timeout, get_time)
        if pulse_start is None:
            return None

        pulse_end = wait_for_edge(echo_pin, GPIO.LOW, timeout, get_time)
        if pulse_end is None:
            return None

        pulse_duration = pulse_end - pulse_start
        distance = (pulse_duration * SOUND_SPEED) / 2
        return distance

    except Exception as e:
        raise RuntimeError(f"Distance measurement failed: {e}")


def wait_for_edge(pin, edge, timeout, get_time=time.time):
    """Waits for a specific edge on the given pin with a timeout."""
    start_time = get_time()
    while GPIO.input(pin) != edge:
        if get_time() - start_time > timeout:
            return None
    return get_time()


def validate_distance(distance, min_distance=MIN_DISTANCE, max_distance=MAX_DISTANCE):
    """Validates the measured distance."""
    if distance is None:
        return None
    if min_distance <= distance <= max_distance:
        return distance
    return None

def main(trigger_pin=TRIGGER_PIN, echo_pin=ECHO_PIN, mode=GPIO_MODE):
    """Main function to continuously measure and print distance."""

    setup_gpio(trigger_pin, echo_pin, mode)
    measure = partial(measure_distance, trigger_pin, echo_pin)
    validate = partial(validate_distance)

    try:
        while True:
            distance = measure()
            valid_distance = validate(distance)

            if valid_distance is not None:
                print(f"Measured Distance = {valid_distance:.1f} cm")
            else:
                print("Invalid distance reading.")

            time.sleep(1)

    except KeyboardInterrupt:
        print("Measurement stopped by User")
    except RuntimeError as e:
        print(f"Error: {e}")
    finally:
        GPIO.cleanup()


if __name__ == "__main__":
    main()

