import time
import smbus2

# I2C address of the PCF8574 expander
PCF8574_ADDRESS = 0x20

# Initialize the I2C bus
try:
    i2c_bus = smbus2.SMBus(1)
except FileNotFoundError:
    print("Error: I2C bus not found. Ensure I2C is enabled.")
    exit()
except Exception as e:
    print(f"Error initializing I2C: {e}")
    exit()

# Configure all pins as inputs with pull-up resistors enabled
try:
    i2c_bus.write_byte(PCF8574_ADDRESS, 0xFF)
except Exception as e:
    print(f"Error configuring PCF8574: {e}")
    exit()

# Function to read the state of the proximity sensors
def read_proximity_sensors():
    """Reads the state of all eight proximity sensors connected to the PCF8574."""
    try:
        sensor_values = i2c_bus.read_byte(PCF8574_ADDRESS)
        return sensor_values
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None

# Main loop to continuously monitor the sensors
try:
    while True:
        sensor_data = read_proximity_sensors()

        if sensor_data is not None:
            # Iterate through each sensor and check for obstacles
            for sensor_index in range(8):
                if (sensor_data >> sensor_index) & 1 == 0:  # Active low
                    print(f"Obstacle detected by sensor {sensor_index}")

        time.sleep(0.1)  # Polling interval

except KeyboardInterrupt:
    print("Program terminated by user.")

except Exception as e:
    print(f"An unexpected error occurred: {e}")

finally:
    # No specific cleanup needed for smbus2, but good practice to include a finally block
    print("Exiting program.")

