import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Configuration
I2C_ADDRESS = 0x70  # Default address of the TCA9548A multiplexer
BME280_CHANNEL = 0  # Channel 0 for BME280 sensor
TSL2591_CHANNEL = 1  # Channel 1 for TSL2591 sensor
READ_INTERVAL_SECONDS = 2  # How often to read the sensors (in seconds)


def initialize_i2c():
    """Sets up the I2C connection."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error setting up I2C: {e}")
        return None


def initialize_multiplexer(i2c_bus):
    """Sets up the I2C multiplexer."""
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus, address=I2C_ADDRESS)
        return multiplexer
    except Exception as e:
        print(f"Error setting up multiplexer: {e}")
        return None


def initialize_bme280(multiplexer):
    """Sets up the BME280 sensor."""
    try:
        bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[BME280_CHANNEL])
        return bme280_sensor
    except Exception as e:
        print(f"Error setting up BME280: {e}")
        return None


def initialize_tsl2591(multiplexer):
    """Sets up the TSL2591 light sensor."""
    try:
        tsl2591_sensor = adafruit_tsl2591.TSL2591(multiplexer[TSL2591_CHANNEL])
        return tsl2591_sensor
    except Exception as e:
        print(f"Error setting up TSL2591: {e}")
        return None


def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Reads data from both sensors."""
    try:
        temperature = bme280_sensor.temperature
        humidity = bme280_sensor.humidity
        light_intensity = tsl2591_sensor.lux

        return temperature, humidity, light_intensity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None


def display_sensor_data(temperature, humidity, light_intensity):
    """Prints the sensor data to the screen."""
    if all(v is not None for v in [temperature, humidity, light_intensity]):
        print(f"Temperature: {temperature:.2f} °C")
        print(f"Humidity: {humidity:.2f} %")
        print(f"Light Intensity: {light_intensity:.2f} lux")
        print("-" * 20)


def main():
    """Main program loop."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280_sensor = initialize_bme280(multiplexer)
    if bme280_sensor is None:
        return

    tsl2591_sensor = initialize_tsl2591(multiplexer)
    if tsl2591_sensor is None:
        return

    try:
        while True:
            temperature, humidity, light_intensity = read_sensor_data(bme280_sensor, tsl2591_sensor)
            display_sensor_data(temperature, humidity, light_intensity)
            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Program stopped by user.")
    finally:
        # No specific cleanup needed for these libraries, but good practice to include
        print("Exiting program.")


if __name__ == "__main__":
    main()

