"""
Reads pressure from a BMP280 sensor and calculates relative altitude using a functional approach.
"""

import time
import logging
from typing import List, Tuple

try:
    from smbus2 import SMBus
except ImportError:
    from smbus import SMBus
from bmp280 import BMP280, CalibrationError

# Configure logging
logging.basicConfig(
    level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s"
)

# Constants
I2C_BUS = 1  # I2C bus number
BMP280_ADDRESS = 0x76  # BMP280 I2C address
BASELINE_SAMPLE_SIZE = 100
BASELINE_TRIM_PERCENTAGE = 0.25
SEA_LEVEL_PRESSURE = 1013.25  # hPa
DEGREE_CELSIUS = 273.15
READING_DELAY = 1  # seconds
NUMBER_OF_READINGS = 10

def initialize_bmp280(bus: SMBus, address: int) -> BMP280:
    """Initializes the BMP280 sensor with error handling."""
    try:
        bmp280 = BMP280(i2c_dev=bus, i2c_addr=address)
        if bmp280.get_CHIP_ID() != 0x58:
            raise OSError("BMP280 not found on I2C bus")
        return bmp280
    except (OSError, CalibrationError) as e:
        raise RuntimeError(f"BMP280 initialization failed: {e}")

def read_pressure(bmp280: BMP280) -> float:
    """Reads pressure from the BMP280 sensor with error handling."""
    try:
        return bmp280.get_pressure()
    except OSError as e:
        raise RuntimeError(f"Error reading pressure: {e}")

def read_temperature(bmp280: BMP280) -> float:
    """Reads temperature from the BMP280 sensor with error handling."""
    try:
        return bmp280.get_temperature()
    except OSError as e:
        raise RuntimeError(f"Error reading temperature: {e}")


def calculate_altitude(qnh: float, pressure: float) -> float:
    """Calculates altitude based on pressure readings."""
    return 44330 * (1 - (pressure / qnh)**(1/5.255))


def create_baseline(bmp280: BMP280, size: int) -> float:
    """Creates a baseline pressure reading with outlier removal."""
    logging.info("Collecting baseline pressure data...")
    pressure_readings = [read_pressure(bmp280) for _ in range(size)]

    sorted_readings = sorted(pressure_readings)
    trimmed_readings = sorted_readings[
        int(size * BASELINE_TRIM_PERCENTAGE) : size - int(size * BASELINE_TRIM_PERCENTAGE)
    ]
    baseline = sum(trimmed_readings) / len(trimmed_readings)
    logging.info(f"Baseline pressure: {baseline:.2f} hPa")
    return baseline


def read_and_calculate_altitude(bmp280: BMP280, baseline: float) -> Tuple[float, float, float]:
    """Reads sensor data and calculates altitude."""
    try:
        temperature = read_temperature(bmp280)
        pressure = read_pressure(bmp280)
        altitude = calculate_altitude(baseline, pressure)
        return temperature, pressure, altitude
    except RuntimeError as e:
        raise


def main_loop(bmp280: BMP280, baseline: float) -> None:
    """Main loop for reading sensor data and calculating altitude."""

    while True:
        try:
            temperature, pressure, altitude = read_and_calculate_altitude(bmp280, baseline)
            print(
                f"Temperature: {temperature:.2f} °C, Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters"
            )
            time.sleep(READING_DELAY)
        except RuntimeError as e:
            logging.error(f"Error during sensor reading: {e}")
            time.sleep(READING_DELAY)


def main() -> None:
    """Main function to initialize and run the sensor reading loop."""
    try:
        with SMBus(I2C_BUS) as bus:
            bmp280 = initialize_bmp280(bus, BMP280_ADDRESS)
            baseline = create_baseline(bmp280, BASELINE_SAMPLE_SIZE)
            main_loop(bmp280, baseline)

    except (RuntimeError, KeyboardInterrupt) as e:
        logging.error(f"Program terminated: {e}")
    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")


if __name__ == "__main__":
    main()

