import time
import json
import urllib.request
import adafruit_dht
import board

# Define sensor and server parameters
DHT_SENSOR = adafruit_dht.DHT11(board.D4)  # DHT11 sensor on GPIO4 (physical pin 7)
SERVER_ADDRESS = 'http://127.0.0.1:5000/data'

def read_sensor_data(sensor):
    """Reads temperature and humidity from the DHT11 sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        return temperature, humidity
    except RuntimeError as error:
        # DHT11 sensors can be unreliable; handle errors gracefully
        print(f"Sensor read error: {error}")
        return None, None

def send_data_to_server(temperature, humidity, server_url):
    """Sends temperature and humidity data to the server as a JSON payload."""
    if temperature is not None and humidity is not None:
        data = {'temperature': temperature, 'humidity': humidity}
        json_data = json.dumps(data).encode('utf-8')
        headers = {'Content-Type': 'application/json'}
        req = urllib.request.Request(server_url, data=json_data, headers=headers, method='POST')
        try:
            with urllib.request.urlopen(req) as response:
                print(f"Server response: {response.status}")
        except urllib.error.URLError as e:
            print(f"Connection error: {e}")
    else:
        print("Invalid sensor data; not sending to server.")

def main():
    """Main function to read sensor data and send it to the server."""
    try:
        while True:
            temperature, humidity = read_sensor_data(DHT_SENSOR)
            send_data_to_server(temperature, humidity, SERVER_ADDRESS)
            time.sleep(5)  # Wait 5 seconds before the next reading
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # No specific cleanup needed for DHT11 library, but good practice to include a finally block
        print("Program finished.")

if __name__ == "__main__":
    main()

