# Environmental monitoring station on Raspberry Pi using pyserial
# Reads temperature and humidity from a UART sensor and alerts on thresholds
import serial
import time

# Serial port configuration for the environmental sensor
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT_SECONDS = 1.0


def parse_sensor_line(raw_line):
    """Parse a comma-separated temperature,humidity line into floats."""
    # Strip whitespace and split the ASCII payload
    cleaned_line = raw_line.strip()
    if not cleaned_line:
        return None, None
    try:
        temperature_value, humidity_value = cleaned_line.split(",")
        return float(temperature_value), float(humidity_value)
    except ValueError:
        return None, None


def evaluate_thresholds(temperature_value, humidity_value):
    """Print an alert when environmental thresholds are exceeded."""
    # Compare readings against configured safety thresholds
    if temperature_value > 30.0:
        print("ALERT: high temperature", temperature_value, "C")
    if humidity_value > 70.0:
        print("ALERT: high humidity", humidity_value, "%")


def main():
    # Open the serial connection to the environmental sensor
    serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT_SECONDS)
    try:
        while True:
            try:
                # Read one line of ASCII data from the sensor
                raw_line = serial_connection.readline().decode("ascii", errors="ignore")
                temperature_value, humidity_value = parse_sensor_line(raw_line)
                if temperature_value is not None and humidity_value is not None:
                    print("Temperature", temperature_value, "C, humidity", humidity_value, "%")
                    evaluate_thresholds(temperature_value, humidity_value)
                time.sleep(1)
            except Exception as read_error:
                print("Read error:", read_error)
                time.sleep(1)
    except KeyboardInterrupt:
        print("Monitoring stopped")
    finally:
        # Close the serial port to release the resource
        serial_connection.close()


if __name__ == "__main__":
    main()

