#!/usr/bin/python
# -*- coding: utf-8 -*-

"""
Control an LED connected to a MCP23017 I2C I/O expander based on a switch input.

This script demonstrates how to use the MCP23017_I2C library to interface
with an MCP23017 chip. It configures GPA0 as an output to drive an LED and
GPB7 as an input with a pull-up resistor. The LED state mirrors the switch
state.

Robust error handling, performance optimization, and modularity are emphasized.
"""

import time
from MCP23017_I2C import GPIO_CHIP, MCP23017_I2C_Error

# Constants
MCP23017_ADDRESS = 0x20
LED_PIN = 0
SWITCH_PIN = 7
POLL_INTERVAL = 0.1  # Seconds

def initialize_mcp23017(gpio_chip):
    """Initialize the MCP23017 configuration."""
    try:
        gpio_chip.setup(LED_PIN, 'OUT', 'A')
        gpio_chip.setup(SWITCH_PIN, 'IN', 'PULLUP', 'B')
    except MCP23017_I2C_Error as e:
        raise RuntimeError(f"MCP23017 initialization failed: {e}")


def read_switch_state(gpio_chip):
    """Read the switch state from the MCP23017."""
    try:
        return gpio_chip.input(SWITCH_PIN, 'B')
    except MCP23017_I2C_Error as e:
        raise MCP23017_I2C_Error(f"Error reading switch state: {e}")

def control_led(gpio_chip, led_state):
    """Control the LED state."""
    try:
        gpio_chip.output(LED_PIN, led_state, 'A')
        print(f"Led {'ON' if led_state else 'OFF'}")  # Print LED status
    except MCP23017_I2C_Error as e:
        raise MCP23017_I2C_Error(f"Error controlling LED: {e}")


def main():
    """Main function to run the LED control loop."""
    try:
        gpio_chip = GPIO_CHIP(MCP23017_ADDRESS, 0)  # Bus 0
        initialize_mcp23017(gpio_chip)

        print("Starting LED control loop. Press Ctrl+C to exit.")
        print("LED ON when switch is closed, OFF when open.\n")

        while True:
            switch_state = read_switch_state(gpio_chip)
            control_led(gpio_chip, not switch_state)  # Invert switch logic
            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program.")
    except MCP23017_I2C_Error as e:
        print(f"I2C Error: {e}")
    except RuntimeError as e:
        print(f"Runtime Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure LED is turned off on exit
        try:
            gpio_chip.output(LED_PIN, 0, 'A')
        except Exception as e:
            print(f"Error turning off LED during cleanup: {e}")
        print("Program terminated.")



if __name__ == "__main__":
    main()

