# Sentiment Analysis on Raspberry Pi (Beginner Tutorial)
# This program performs basic sentiment analysis on user input using a simplified lexicon.
# It optionally controls LEDs to indicate sentiment.

import time
import sys

try:
    import RPi.GPIO as GPIO  # Optional: For LED control
    LED_AVAILABLE = True
except ImportError:
    print("RPi.GPIO not found, running without LED control.")
    LED_AVAILABLE = False

# Simplified sentiment lexicon (word: score)
vader_lexicon = {
    "good": 0.9, "great": 1.0, "excellent": 1.0, "happy": 0.8, "love": 0.9,
    "bad": -0.9, "terrible": -1.0, "awful": -1.0, "sad": -0.8, "hate": -0.9,
    "okay": 0.0, "fine": 0.1, "normal": 0.0, "average": 0.0, "nice": 0.6,
    "not": -0.2, "very": 0.3, "extremely": 0.4, "little": -0.1, "quite": 0.2
}

# LED pin definitions (if using LEDs)
if LED_AVAILABLE:
    GREEN_LED = 17  # GPIO pin for positive sentiment
    RED_LED = 18   # GPIO pin for negative sentiment

    GPIO.setmode(GPIO.BCM)  # Use Broadcom pin numbering
    GPIO.setup(GREEN_LED, GPIO.OUT)
    GPIO.setup(RED_LED, GPIO.OUT)
    GPIO.output(GREEN_LED, GPIO.LOW)  # Initially off
    GPIO.output(RED_LED, GPIO.LOW)   # Initially off


def analyze_sentiment(text):
    """Analyzes the sentiment of a given text using a simplified lexicon."""
    words = text.lower().split()  # Tokenize the text (lowercase and split)
    total_score = 0.0
    word_count = 0

    for word in words:
        if word in vader_lexicon:
            total_score += vader_lexicon[word]
            word_count += 1

    if word_count > 0:
        average_score = total_score / word_count
    else:
        average_score = 0.0  # Handle empty input

    return average_score


def classify_sentiment(score):
    """Classifies the sentiment based on the average score."""
    if score > 0.2:
        return "Positive"
    elif score < -0.2:
        return "Negative"
    else:
        return "Neutral"


def control_leds(sentiment):
    """Controls the LEDs based on the sentiment (if LEDs are available)."""
    if not LED_AVAILABLE:
        return

    if sentiment == "Positive":
        GPIO.output(GREEN_LED, GPIO.HIGH)
        GPIO.output(RED_LED, GPIO.LOW)
    elif sentiment == "Negative":
        GPIO.output(GREEN_LED, GPIO.LOW)
        GPIO.output(RED_LED, GPIO.HIGH)
    else:
        GPIO.output(GREEN_LED, GPIO.LOW)
        GPIO.output(RED_LED, GPIO.LOW)

    time.sleep(2)  # Keep LEDs on for 2 seconds
    GPIO.output(GREEN_LED, GPIO.LOW)
    GPIO.output(RED_LED, GPIO.LOW)


if __name__ == "__main__":
    try:
        user_input = input("Enter a sentence for sentiment analysis: ")
        sentiment_score = analyze_sentiment(user_input)
        sentiment = classify_sentiment(sentiment_score)

        print(f"Sentiment: {sentiment} (Score: {sentiment_score:.2f})")

        control_leds(sentiment)  # Control LEDs based on sentiment

    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if LED_AVAILABLE:
            GPIO.cleanup()  # Clean up GPIO on exit

