    """Turns the LED on and displays a confirmation message."""
    if led:
        led.on()
        return render_template_string(
            "<h1>Light ON</h1><a href='/'>Back</a>"
        )
    else:
        return render_template_string("<h1>Error: LED control unavailable.</h1>")

