import RPi.GPIO as GPIO
import time
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants for GPIO pin numbers (BCM numbering)
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Protocol Constants
START_SIGNAL = [1, 0, 1, 1, 1, 1, 1, 1]
END_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1]
BASE_BUFFER = [0, 0, 0, 0, 0, 0, 0, 0]

# Timing constants (seconds)
TRANSMIT_DELAY = 0.0005
RECEPTION_TIMEOUT = 1  # Timeout in seconds for reception

# Global variable to control the main loop
running = True

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global running
    logging.info('Received signal, stopping...')
    running = False

# Register signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def initialize_gpio():
    """Initializes GPIO pins and sets up the GPIO mode."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)  # Disable warnings
        return True
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        return False

def char_to_buffer(char: str) -> list:
    """Converts a character to a buffer (list of 8 bits)."""
    if not isinstance(char, str) or len(char) != 1:
        raise ValueError("Input must be a single character.")

    ascii_value = ord(char)
    return [0] + [int(bit) for bit in bin(ascii_value)[2:].zfill(7)]


def buffer_to_char(buffer: list) -> str:
    """Converts a buffer (list of 8 bits) to a character."""
    if not isinstance(buffer, list) or len(buffer) != 8 or not all(isinstance(bit, int) for bit in buffer):
        raise ValueError("Input must be a list of 8 integers.")

    return chr(int("".join(map(str, buffer[1:])), 2))


def string_to_buffer_list(input_string: str) -> list[list]:
    """Converts a string to a list of buffers."""
    if not isinstance(input_string, str):
        raise ValueError("Input must be a string.")
    return [char_to_buffer(char) for char in input_string]


def buffer_list_to_string(buffer_list: list[list]) -> str:
    """Converts a list of buffers to a string."""
    if not isinstance(buffer_list, list):
        raise ValueError("Input must be a list.")
    return "".join(buffer_to_char(buffer) for buffer in buffer_list if buffer not in (START_SIGNAL, END_SIGNAL))


def transmit_bit(bit: int, data_pin: int, timer_pin: int):
    """Transmits a single bit."""
    if bit not in (0, 1):
        raise ValueError("Bit must be 0 or 1.")

    GPIO.output(timer_pin, GPIO.LOW)
    GPIO.output(data_pin, bit)
    time.sleep(TRANSMIT_DELAY)
    GPIO.output(timer_pin, GPIO.HIGH)
    time.sleep(TRANSMIT_DELAY)
    GPIO.output(timer_pin, GPIO.LOW)


def transmit_buffer(buffer: list, data_pin: int, timer_pin: int):
    """Transmits a buffer (list of bits)."""
    if not isinstance(buffer, list) or not all(isinstance(bit, int) for bit in buffer):
        raise ValueError("Buffer must be a list of integers.")

    for bit in buffer:
        transmit_bit(bit, data_pin, timer_pin)
    time.sleep(TRANSMIT_DELAY)


def send_data(data_string: str, data_pin: int, timer_pin: int):
    """Sends a string over the data protocol."""
    if not initialize_gpio():
        return False

    try:
        GPIO.setup(data_pin, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(timer_pin, GPIO.OUT, initial=GPIO.LOW)

        buffers_to_send = string_to_buffer_list(data_string) + [END_SIGNAL]
        for buffer in buffers_to_send:
            transmit_buffer(buffer, data_pin, timer_pin)

        logging.info(f"Sent data: {data_string}")

    except Exception as e:
        logging.error(f"Error during data transmission: {e}")
        return False

    finally:
        GPIO.cleanup()  # Clean up GPIO pins
        return True


def receive_bit(data_pin: int, timer_pin: int, timeout: float) -> int:
    """Receives a single bit with a timeout."""
    start_time = time.time()
    while GPIO.input(timer_pin) == GPIO.LOW:
        if time.time() - start_time > timeout:
            raise TimeoutError("Timeout receiving bit.")
    return GPIO.input(data_pin)

def receive_buffer(data_pin: int, timer_pin: int, timeout: float) -> list:
    """Receives a buffer (8 bits) with timeout handling."""
    buffer = []
    for _ in range(8):
        try:
            bit = receive_bit(data_pin, timer_pin, timeout)
            buffer.append(bit)
        except TimeoutError:
            raise

    return buffer


def receive_data(data_pin: int, timer_pin: int, timeout: float = RECEPTION_TIMEOUT) -> str:
    """Receives data with timeout handling and signal verification."""
    if not initialize_gpio():
        return ""

    try:
        GPIO.setup(data_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(timer_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

        received_buffers = []
        start_time = time.time()

        while True:  # Keep receiving until END_SIGNAL or timeout
            if time.time() - start_time > timeout:
                raise TimeoutError("Timeout receiving data.")

            try:
                buffer = receive_buffer(data_pin, timer_pin, timeout)
            except TimeoutError:
                raise

            received_buffers.append(buffer)

            if buffer == END_SIGNAL:
                break

        # Verify start signal
        if received_buffers[0] != START_SIGNAL:
            logging.error("Missing or incorrect start signal.")
            return ""

        # Convert buffers to string, excluding start and end signals
        return buffer_list_to_string(received_buffers[1:-1])

    except Exception as e:
        logging.error(f"Error during data reception: {e}")
        return ""

    finally:
        GPIO.cleanup()
        return ""


def main():
    """Main function to demonstrate data transmission and reception."""
