    def _handle_timeout(self):
        """Handles timeouts and sets the error output."""
        if time.time() - self.last_msg > 20:
            self.logger.warning("No data received for 20 seconds. Triggering error output.")
            self.set_error_output(True)  # Set error output to True
            self.last_msg = time.time()

    def _update_pid(self, event: dict):
        """Updates a PID controller."""
        channel_id = event['id']
        if channel_id not in self.pids:
            self.pids[channel_id] = WDAC8532(0.0, 0.01, 0.00, 1.0, 0.0, 100.0, logger=self.logger)
            self.pids[channel_id].set_output(0.0)
        try:
            self.pids[channel_id].update(event)
        except Exception:
            self.logger.exception("Failed to update PID with: %s" % event)

    def _mute_all_channels(self, event: dict):
        """Mutes or unmutes all channels."""
        muted = event['action'] == 'MUTE'
        for pid in self.pids.values():
            pid.mute(muted)

    def _reset_channel(self, event: dict):
        """Resets a specific PID channel."""
        channel_id = event['id']
        if channel_id in self.pids:
            self.pids[channel_id].reset()

    def _reset_all_channels(self, event: dict):
        """Resets all PID channels."""
        for pid in self.pids.values():
            pid.reset()

    def set_error_output(self, state: bool):
        """Sets the error output."""
        if self.error_output is None:
            try:
                self.error_output = GPIO.PWM(12, 1000)
                self.error_output.start(0.0)
            except Exception as e:
                self.logger.error("Failed to initialize PWM on GPIO 12: %s" % str(e))
                return

        if state:
            self.error_output.ChangeDutyCycle(100.0)
        else:
            self.error_output.ChangeDutyCycle(0.0)


def main():
    """Entry point for the PID handler."""
    logger = logging.getLogger(__name__)
    logger.setLevel(logging.DEBUG)

    handler = PIDHandler(logger)
    sub_sock = setup_subscriber_socket() # Implement this function to set up your ZMQ subscriber socket

    try:
        while True:
            handler.update(sub_sock)
            time.sleep(0.1)
    except KeyboardInterrupt:
        logger.info("Shutting down.")
    finally:
        if handler.error_output is not None:
            handler.error_output.stop()
        GPIO.cleanup()


if __name__ == "__main__":
    main()

