#!/usr/bin/env python3
"""Module for managing a garage door using a Raspberry Pi and Automation HAT in a functional style."""

import time
import automationhat
import logging
from typing import Callable, Union

# Configure logging for debugging and error tracking
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Type alias for a function that performs an action and returns a boolean (success/failure)
Action = Callable[[], bool]

def check_automation_hat() -> bool:
    """Checks if the Automation HAT is detected and initialized."""
    try:
        if not automationhat.is_present():
            logging.error("Automation HAT not detected. Please ensure it is properly connected.")
            return False
        return True
    except Exception as e:
        logging.error(f"Error checking Automation HAT: {e}")
        return False

def create_garage_door(state_pin: int) -> Union['GarageDoor', None]:
    """Creates a GarageDoor object after validating input parameters."""
    if not isinstance(state_pin, int) or not 1 <= state_pin <= 3:
        logging.error("Invalid state_pin provided. Must be an integer between 1 and 3.")
        return None
    if not check_automation_hat():
        return None
    return GarageDoor(state_pin)


class GarageDoor:
    """Represents a garage door controlled by a Raspberry Pi and Automation HAT."""

    def __init__(self, state_pin: int):
        """Initializes the GarageDoor object."""
        self.state_pin = state_pin
        logging.info(f"Garage door initialized with state pin: {self.state_pin}")

    def _read_state_pin(self) -> Union[int, None]:
        """Reads the state pin and handles potential errors."""
        try:
            return automationhat.input[self.state_pin - 1].read()
        except Exception as e:
            logging.error(f"Error reading state pin {self.state_pin}: {e}")
            return None

    def get_state(self) -> Union[bool, None]:
        """Returns the current state of the garage door (True for closed, False for open)."""
        state = self._read_state_pin()
        if state is None:
            return None  # Propagate the error
        return bool(state)

    def trigger(self) -> bool:
        """Triggers the garage door relay to open or close it."""
        try:
            automationhat.relay.one.on()
            time.sleep(0.5)
            automationhat.relay.one.off()
            logging.info("Garage door triggered.")
            return True
        except Exception as e:
            logging.error(f"Error triggering garage door: {e}")
            return False

    def open_door(self) -> bool:
        """Opens the garage door if it is currently closed."""
        current_state = self.get_state()
        if current_state is None:
            return False  # Propagate the error
        if current_state:  # Door is closed
            logging.info("Opening garage door.")
            return self.trigger()
        else:  # Door is already open
            logging.info("Garage door is already open.")
            return True

    def close_door(self) -> bool:
        """Closes the garage door if it is currently open."""
        current_state = self.get_state()
        if current_state is None:
            return False # Propagate the error
        if not current_state:  # Door is open
            logging.info("Closing garage door.")
            return self.trigger()
        else:  # Door is already closed
            logging.info("Garage door is already closed.")
            return True

    def toggle_door(self) -> bool:
        """Toggles the garage door state (opens if closed, closes if open)."""
        logging.info("Toggling garage door.")
        if self.get_state() is None:
            return False # Propagate the error
        if self.get_state():
            return self.close_door()
        else:
            return self.open_door()


def main():
    """Main function to demonstrate garage door control."""

    garage = create_garage_door(1)
    if garage is None:
        return

    try:
        # Example usage:
        garage.open_door()
        time.sleep(5)
        garage.close_door()

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Ensure relay is off on exit
        automationhat.relay.one.off()
        logging.info("Garage door control finished.")


if __name__ == "__main__":
    main()

