        try:
            self.laser = OutputDevice(pin)
        except Exception as e:
            print(f"Error initializing laser: {e}")
            exit()

    def on(self):
        self.laser.on()

    def off(self):
        self.laser.off()

    def close(self):
        self.laser.close()


class Aim:
    def __init__(self, ld, sd):
        self.ld = ld
        self.sd = sd
        self.hp = [0.0, 0.14285714285714285, 0.2857142857142857, 0.42857142857142855, 0.5714285714285714, 0.7142857142857143, 0.8571428571428571, 1.0, 0.8571428571428571, 0.7142857142857143, 0.5714285714285714]
        self.vp = [1.0, 0.8571428571428571, 0.7142857142857143, 0.5714285714285714, 0.42857142857142855, 0.2857142857142857, 0.14285714285714285, 0.0, 0.14285714285714285, 0.2857142857142857, 0.42857142857142855]
        self.h = Servo(18) # Horizontal servo
        self.v = Servo(19) # Vertical servo

    def aim(self, nums):
        try:
            for n in sorted(nums, key=lambda x: nums.index(x) + 1): # Maintain original order
                self.move(n)
                sleep(self.sd / 2)
                self.laser.on()
                sleep(self.ld)
                self.laser.off()
                sleep(self.sd / 2)
                self.move(10) # Return to rest position
        except Exception as e:
            print(f"Error during aiming: {e}")

    def move(self, b):
        try:
            self.h.value = self.hp[b-1]
            self.v.value = self.vp[b-1]
        except Exception as e:
            print(f"Error moving servo: {e}")

    def close(self):
        self.h.close()
        self.v.close()


