import time
import board
import busio
import RPi.GPIO as GPIO
from adafruit_servokit import ServoKit
from typing import Callable, Tuple

# Constants
SERVO_CHANNELS = 16
DEFAULT_ANGLE = 90
MIN_ANGLE = 0
MAX_ANGLE = 180
I2C_ADDRESS = 0x40
I2C_BUS = 1
BASE_SERVO = 0
DROP_SERVO = 1
SEEK_SERVO = 2
GRAB_SERVO = 4

# Initialize I2C and ServoKit
try:
    i2c = busio.I2C(board.SCL, board.SDA, address=I2C_ADDRESS, busnum=I2C_BUS)
    kit = ServoKit(channels=SERVO_CHANNELS)
except Exception as e:
    print(f"Error initializing I2C or ServoKit: {e}")
    exit(1)


def angle_within_range(angle: int) -> int:
    """Clamps angle within valid range."""
    return max(MIN_ANGLE, min(angle, MAX_ANGLE))


def move_servo(channel: int, target_angle: int, step_size: int = 5, delay: float = 0.04) -> None:
    """Moves a servo smoothly to a target angle."""
    if not 0 <= channel < SERVO_CHANNELS:
        raise ValueError("Invalid servo channel.")

    target_angle = angle_within_range(target_angle)

    try:
        current_angle = kit.servo[channel].angle or DEFAULT_ANGLE  # Handle potential None value
        step = step_size if target_angle > current_angle else -step_size

        while angle_within_range(current_angle) != target_angle:
            current_angle = angle_within_range(current_angle + step)
            kit.servo[channel].angle = current_angle
            time.sleep(delay)
    except Exception as e:
        print(f"Error moving servo {channel}: {e}")


def create_servo_control(channel: int) -> Callable[[int], None]:
    """Creates a function to control a specific servo."""
    def control_servo(angle: int) -> None:
        move_servo(channel, angle)
    return control_servo


move_base = create_servo_control(BASE_SERVO)
move_drop = create_servo_control(DROP_SERVO)
move_seek = create_servo_control(SEEK_SERVO)
move_grab = create_servo_control(GRAB_SERVO)


def collect_object_steps(seek_angle: int, drop_angle: int) -> None:
    """Sequence of actions to collect an object."""
    try:
        move_seek(seek_angle)
        move_drop(160)
        move_grab(90)
        move_drop(100)
        move_seek(DEFAULT_ANGLE)  # Return to default after seeking
    except Exception as e:
        print(f"Error during collect_object_steps: {e}")


def drop_object_steps(drop_angle: int) -> None:
    """Steps to drop an object."""
    try:
        move_drop(drop_angle)
        move_grab(120)  # Open gripper while dropping
        move_drop(DEFAULT_ANGLE) # Return to default drop angle
    except Exception as e:
        print(f"Error during drop_object_steps: {e}")


def get_pos_x(x_center: int, min_val: int = 0, max_val: int = 320) -> int:
    """Maps x_center to an angle, handling range errors."""
    if x_center < min_val or x_center > max_val:
        raise ValueError(f"x_center {x_center} out of range ({min_val}-{max_val})")
    return angle_within_range(int((x_center - min_val) * MAX_ANGLE / (max_val - min_val)))


def get_pos_y(y_center: int, min_val: int = 0, max_val: int = 240) -> int:
    """Maps y_center to an angle, handling range errors."""
    if y_center < min_val or y_center > max_val:
        raise ValueError(f"y_center {y_center} out of range ({min_val}-{max_val})")
    return angle_within_range(int((max_val - y_center) * MAX_ANGLE / (max_val - min_val)))


def collect_object(x_center: int, y_center: int, drop_angle: int) -> None:
    """Collects an object based on its position."""
    try:
        pos_x = get_pos_x(x_center)
        pos_y = get_pos_y(y_center)

        move_base(pos_x)  # Move base servo
        collect_object_steps(pos_y, drop_angle)  # Execute collection steps

    except ValueError as e:
        print(f"Error collecting object: {e}")
    except Exception as e:
        print(f"An unexpected error occurred during collect_object: {e}")


def drop_object(metal_angle: int, plastic_angle: int, paper_angle: int) -> None:
    """Drops objects based on type."""
    try:
        move_seek(metal_angle)
        drop_object_steps(135)
        move_seek(DEFAULT_ANGLE);

        move_seek(plastic_angle)
        drop_object_steps(180)
        move_seek(DEFAULT_ANGLE);

        move_seek(paper_angle)
        drop_object_steps(90)
        move_seek(DEFAULT_ANGLE);

    except Exception as e:
        print(f"Error during drop_object: {e}")


def main() -> None:
    """Main function to run the robot arm sequence."""
    try:
        collect_object(160, 120, 90)  # Example usage
        drop_object(135, 180, 90)

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Cleanup (if needed) - stop servos, release resources, etc.
        print("Program exiting.")


if __name__ == "__main__":
    main()

