#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock (RTC) Driver for Raspberry Pi

This module provides a driver for the DS1338 RTC chip, utilizing the I2C interface.
It offers functionalities to read and write date and time information to the RTC.
"""

import smbus2 as smbus
from datetime import datetime
import logging
import os

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants for I2C bus and device address
DEFAULT_I2C_BUS = 1
DEFAULT_DEVICE_ADDRESS = 0x68

# Register addresses for the DS1338
REGISTERS = {
    "seconds": 0x00,
    "minutes": 0x01,
    "hours": 0x02,
    "day": 0x03,
    "date": 0x04,
    "month": 0x05,
    "year": 0x06,
    "control": 0x07
}


def bcd_to_int(bcd_value):
    """Converts a BCD value to an integer."""
    try:
        return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
    except TypeError:
        logger.exception("Invalid BCD value provided: %s", bcd_value)
        return None


def int_to_bcd(int_value):
    """Converts an integer to BCD format."""
    if not 0 <= int_value <= 99:
        raise ValueError("Integer value must be between 0 and 99 for BCD conversion.")
    return (int_value // 10 << 4) | (int_value % 10)


def read_register(bus, register):
    """Reads a byte from the specified register."""
    try:
        return bus.read_byte_data(DEFAULT_DEVICE_ADDRESS, register)
    except OSError as e:
        logger.error("I2C read error: %s", e)
        raise


def write_register(bus, register, value):
    """Writes a byte to the specified register."""
    try:
        bus.write_byte_data(DEFAULT_DEVICE_ADDRESS, register, value)
    except OSError as e:
        logger.error("I2C write error: %s", e)
        raise



def read_time_component(bus, component):
    """Reads a specific time component from the RTC."""
    register = REGISTERS.get(component)
    if register is None:
        raise ValueError("Invalid time component specified.")

    if component == "hours":
        return bcd_to_int(read_register(bus, register) & 0x3F)
    else:
        return bcd_to_int(read_register(bus, register))



def read_all(bus):
    """Reads all time components from the RTC."""
    try:
        time_components = ["year", "month", "date", "day", "hours", "minutes", "seconds"]
        return tuple(read_time_component(bus, component) for component in time_components)
    except Exception as e:
        logger.exception("Error reading all RTC data: %s", e)
        raise



def read_datetime(bus, century=21):
    """Reads the date and time and returns a datetime object."""
    try:
        year, month, date, day, hours, minutes, seconds = read_all(bus)
        year = (century - 1) * 100 + year
        return datetime(year, month, date, hours, minutes, seconds)
    except Exception as e:
        logger.exception("Error constructing datetime object: %s", e)
        raise



def write_time_component(bus, component, value):
    """Writes a specific time component to the RTC."""

    if value is not None:
        if component not in ["year", "month", "date", "day", "hours", "minutes", "seconds"]:
            raise ValueError("Invalid time component specified.")

        if component == "hours" and value > 23:
            raise ValueError("Hours must be between 0 and 23.")
        if component in ["minutes", "seconds"] and value > 59:
            raise ValueError("Minutes and seconds must be between 0 and 59.")

        bcd_value = int_to_bcd(value)
        write_register(bus, REGISTERS[component], bcd_value)



def write_all(bus, seconds=None, minutes=None, hours=None, day=None, date=None, month=None, year=None):
    """Writes all time components to the RTC."""
    try:
        write_time_component(bus, "seconds", seconds)
        write_time_component(bus, "minutes", minutes)
        write_time_component(bus, "hours", hours)
        write_time_component(bus, "day", day)
        write_time_component(bus, "date", date)
        write_time_component(bus, "month", month)
        write_time_component(bus, "year", year)
    except Exception as e:
        logger.exception("Error writing to RTC: %s", e)
        raise



class DS1338:
    """Driver class for the DS1338 RTC chip."""

    def __init__(self, i2c_bus=DEFAULT_I2C_BUS, device_address=DEFAULT_DEVICE_ADDRESS):
        self.i2c_bus = i2c_bus
        self.device_address = device_address
        self.bus = None

    def begin(self):
        """Initializes the RTC driver."""
        try:
            self.bus = smbus.SMBus(self.i2c_bus)
            logger.info("DS1338 initialized on I2C bus %s at address 0x%02X", self.i2c_bus, self.device_address)
        except Exception as e:
            logger.error("Failed to initialize DS1338: %s", e)
            raise

    def end(self):
        """Closes the I2C connection."""
        if self.bus:
            try:
                self.bus.close()
                logger.info("I2C connection closed.")
            except Exception as e:
                logger.error("Error closing I2C connection: %s", e)
            finally:
                self.bus = None

    def is_present(self):
        """Checks if the DS1338 is present on the I2C bus."""
        if self.bus is None:
            return False
        try:
            return self.bus.read_byte(self.device_address) != 0x00
        except OSError:
            return False

    def _read_register(self, register):
        return read_register(self.bus, register)

    def _write_register(self, register, value):
        return write_register(self.bus, register, value)


    def read_seconds(self):
        return read_time_component(self.bus, "seconds")
    # ... (Similarly implement other read and write methods)


    def read_all(self):
        return read_all(self.bus)

    def read_datetime(self, century=21):
        return read_datetime(self.bus, century)


    def write_all(self, seconds=None, minutes=None, hours=None, day=None, date=None, month=None, year=None):
        write_all(self.bus, seconds, minutes, hours, day, date, month, year)


    def get_cpu_temperature(self):
        """Retrieves the CPU temperature."""
        try:
            with open("/sys/class/thermal/thermal_zone0/temp", "r") as temp_file:
                temp_celsius = float(temp_file.read()) / 1000.0
                return temp_celsius
        except (FileNotFoundError, IOError, ValueError) as e:
            logger.error("Error reading CPU temperature: %s", e)
            return None

