# Reads water flow data from a UART sensor and triggers an alert if flow exceeds a threshold.
# Target: Raspberry Pi 4 Model B
# Context: Smart Retail (e.g., monitoring water usage in a beverage dispenser)

import serial
import time
import RPi.GPIO as GPIO
import gpiozero

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALERT_THRESHOLD = 10.0  # L/min
ALERT_PIN = 17  # BCM numbering

def initialize_serial(port, baud, timeout):
    """Initializes the serial port."""
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def initialize_gpio(pin):
    """Initializes the GPIO pin for the alert."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT)
        return gpiozero.OutputDevice(pin)
    except Exception as e:
        print(f"Error initializing GPIO pin: {e}")
        return None

def read_flow_data(serial_port):
    """Reads flow data from the serial port."""
    try:
        data = serial_port.readline().decode('ascii', errors='replace').strip()
        return data
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def process_flow_data(data):
    """Processes the flow data and returns the flow rate."""
    if data:
        try:
            flow_rate = float(data)
            return flow_rate
        except ValueError:
            print(f"Invalid data received: {data}")
            return None
    return None

def trigger_alert(alert_device, flow_rate, threshold):
    """Triggers an alert if the flow rate exceeds the threshold."""
    if flow_rate is not None:
        if flow_rate > threshold:
            alert_device.on()
        else:
            alert_device.off()

def main():
    """Main function to read flow data and trigger alerts."""
    serial_port = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_port is None:
        exit(1)

    alert_device = initialize_gpio(ALERT_PIN)
    if alert_device is None:
        serial_port.close()
        exit(1)

    try:
        while True:
            flow_data = read_flow_data(serial_port)
            flow_rate = process_flow_data(flow_data)

            if flow_rate is not None:
                print(f'Flow Rate: {flow_rate} L/min')
                trigger_alert(alert_device, flow_rate, ALERT_THRESHOLD)

            time.sleep(1)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        serial_port.close()
        GPIO.cleanup()
        alert_device.close()

if __name__ == "__main__":
    main()

