#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Simple Flask-RESTPlus API for beginners, managing data and interacting with a serial device.
"""

import logging
import signal
import sys
from threading import Thread, Lock
from time import sleep

import serial
from flask import Flask, Response, request, jsonify, abort
from flask_restplus import Api, Resource

# --- Configuration ---
SERIAL_PORT = '/dev/ttyUSB0'
SERIAL_BAUDRATE = 9600
MODEL_NAME = 'Web2uart Control'
DATA_STORE_SAMPLE = [{'id': 1, 'name': 'CHIPS', 'done': False}, {'id': 2, 'name': 'garden', 'done': False}]

# --- Logging ---
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# --- Global Variables ---
app = Flask(__name__)
api = Api(app, version='1.0', title='Web2uart API', description='A simple API for data and serial control')
ns = api.namespace('data', description='Data operations')
serial_port = None  # Global serial port object
serial_lock = Lock()  # Lock for serial communication

# --- Data Model ---
data_store = ThreadSafeList(DATA_STORE_SAMPLE)  # Our simple data store


class ThreadSafeList(list):
    """A simple thread-safe list using a lock."""

    def __init__(self, initial=None):
        super().__init__(initial if initial else [])
        self.lock = Lock()

    def add(self, item):
        with self.lock:
            self.append(item)

    def get(self, index):
        with self.lock:
            return self[index]

    def all(self):
        with self.lock:
            return list(self)  # Return a copy


# --- Serial Communication Class ---
class SerialCommunicator:
    """Handles serial communication in a thread-safe manner."""

    def __init__(self, port, baudrate):
        self.port = port
        self.baudrate = baudrate
        self.ser = None
        self.lock = Lock()

    def open(self):
        """Opens the serial port."""
        with self.lock:
            try:
                if self.ser and self.ser.is_open:
                    return  # Already open
                self.ser = serial.Serial(self.port, self.baudrate, timeout=1)  # 1 second timeout
                logger.info(f"Serial port {self.port} opened successfully.")
            except serial.SerialException as e:
                logger.error(f"Error opening serial port: {e}")
                raise

    def close(self):
        """Closes the serial port."""
        with self.lock:
            if self.ser and self.ser.is_open:
                self.ser.close()
                logger.info(f"Serial port {self.port} closed.")
                self.ser = None

    def send(self, message):
        """Sends a message over the serial port."""
        with self.lock:
            try:
                if not self.ser or not self.ser.is_open:
                    raise serial.SerialException("Serial port not open")
                encoded_message = message.encode('utf-8')
                self.ser.write(encoded_message)
                logger.debug(f"Sent: {message}")
                return len(encoded_message)
            except serial.SerialException as e:
                logger.error(f"Error sending data: {e}")
                raise

    def receive(self):
        """Receives data from the serial port."""
        with self.lock:
            try:
                if not self.ser or not self.ser.is_open:
                    raise serial.SerialException("Serial port not open")
                response = self.ser.readline().decode('utf-8', errors='replace').strip() # Read a single line
                logger.debug(f"Received: {response}")
                return response
            except serial.SerialException as e:
                logger.error(f"Error receiving data: {e}")
                raise


# --- Initialize Serial Communicator ---
serial_communicator = SerialCommunicator(SERIAL_PORT, SERIAL_BAUDRATE)


# --- Signal Handler ---
def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logger.info('Shutting down...')
    try:
        serial_communicator.close()
    except Exception as e:
        logger.error(f"Error during shutdown: {e}")
    sys.exit(0)


signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)


# --- API Resources ---
@ns.route('/')
class DataList(Resource):
    """Lists all data items."""

    def get(self):
        """Returns all data items."""
        return jsonify(data_store.all())


@ns.route('/<int:item_id>')
class DataItem(Resource):
    """Handles operations for a specific data item."""

    def get(self, item_id):
        """Returns a specific data item."""
        try:
            item = data_store.get(item_id - 1)
            if item is None:
                abort(404, description="Item not found")
            return jsonify(item)
        except IndexError:
            abort(404, description="Item not found")

    @ns.response(201, 'Item Created')
    @ns.response(400, 'Invalid Input')
    def post(self, item_id):
        """Creates a new data item (not truly creating at an ID, more like updating)."""
        body = request.get_json()
        if not body or 'name' not in body or 'done' not in body:
            abort(400, description="Missing 'name' or 'done' in request body")

        try:
            name = body['name']
            done = body['done']
            if not isinstance(name, str) or not isinstance(done, bool):
                abort(400, description="Invalid 'name' or 'done' type")

            new_item = {'id': item_id, 'name': name, 'done': done}
            data_store.add(new_item)  # Add the new item
            return jsonify(new_item), 201

        except (KeyError, TypeError) as e:
            logger.error(f"Error processing request: {e}")
            abort(400, description=str(e))


@ns.route('/version')
class Version(Resource):
    """Retrieves the device version information via serial."""

    def get(self):
        """Gets version info from the serial device."""
        try:
            serial_communicator.open()  # Ensure the port is open
            serial_communicator.send('*IDN?\n')
            response = serial_communicator.receive()
            if response:
                return Response(response + '\n', mimetype='text/plain')
            else:
                return Response("No response received from the device.\n", mimetype='text/plain', status=504)
        except serial.SerialException as e:
            logger.error(f"Serial communication error: {e}")
            return Response(f"Serial communication error: {e}\n", mimetype='text/plain', status=502)
        finally:
            try:
                serial_communicator.close()
            except Exception as e:
                logger.error(f"Error closing serial port during version request: {e}")


# --- Run the API ---
if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', port=5000, debug=False)
    except Exception as e:
        logger.critical(f"Unhandled exception: {e}")
    finally:
        try:
            serial_communicator.close()
        except Exception as e:
            logger.error(f"Error closing serial port on exit: {e}")

