import serial
import time
import os
import sys

# Configuration for the serial port
SERIAL_PORT = '/dev/serial0'  # UART port on Raspberry Pi
BAUD_RATE = 9600
TIMEOUT = 1  # seconds

# Log file path
LOG_FILE = 'power_consumption.log'

def read_power_data():
    """Reads power data from the serial port and logs it."""
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f"Connected to serial port: {SERIAL_PORT}")
            while True:
                try:
                    line = ser.readline().decode('ascii', errors='replace').strip()
                    if line:
                        try:
                            power_value = float(line)
                            log_power_consumption(power_value)
                        except ValueError:
                            print(f"Warning: Non-numeric data received: {line}", file=sys.stderr)
                except serial.SerialException as e:
                    print(f"Serial error: {e}", file=sys.stderr)
                    break  # Exit loop on serial error
                except Exception as e:
                    print(f"Error reading data: {e}", file=sys.stderr)
                    break # Exit loop on any other error
    except serial.SerialException as e:
        print(f"Could not open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
    except OSError as e:
        print(f"OS error: {e}", file=sys.stderr)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        print("Program finished.")

def log_power_consumption(power):
    """Logs the power consumption to a file."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Power: {power} W\n'
    try:
        with open(LOG_FILE, 'a') as logfile:
            logfile.write(log_entry)
        print(f'Power Consumption: {power} W')
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

if __name__ == "__main__":
    read_power_data()

