from flask import Flask, Response, request, jsonify, abort
import json
import time
import serial
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

app = Flask(__name__)

# In-memory data store
DATA_STORE = [{"id": 1, "name": "CHIPS", "done": False}, {"id": 2, "name": "garden", "done": False}]

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
SERIAL_BAUDRATE = 9600
SERIAL_TIMEOUT = 1


def get_serial_connection():
    """Establishes a serial connection and returns the port object.  Handles potential errors."""
    try:
        port = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=SERIAL_TIMEOUT)
        logging.info(f"Serial connection established on {SERIAL_PORT} at {SERIAL_BAUDRATE} baud.")
        return port
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port {SERIAL_PORT}: {e}")
        return None


def close_serial_connection(port):
    """Closes the serial connection if it's open."""
    if port and port.is_open:
        try:
            port.close()
            logging.info("Serial port closed successfully.")
        except serial.SerialException as e:
            logging.error(f"Failed to close serial port: {e}")


def send_scpi_command(port, command):
    """Sends an SCPI command to the instrument via serial and returns the response."""
    if not port:
        logging.error("Serial port not initialized.")
        return None

    try:
        port.write(command.encode('utf-8'))
        response = port.read_all().decode('utf-8').strip()  # Read all available data
        logging.debug(f"Sent command: {command}, Received response: {response}")
        return response
    except serial.SerialException as e:
        logging.error(f"Serial communication error: {e}")
        return None


@app.route('/version', methods=['GET'])
def version():
    """Retrieves the instrument version information via SCPI command."""
    port = get_serial_connection()
    if not port:
        return Response("Serial port not available", status=503, mimetype='text/html')

    response = send_scpi_command(port, "*IDN?\n")
    close_serial_connection(port)

    if response:
        return Response(response, mimetype='text/html')
    else:
        return Response("Failed to retrieve version information", status=500, mimetype='text/html')


@app.route('/getdata', methods=['GET'])
def get_data():
    """Returns the entire data store as JSON."""
    return jsonify(DATA_STORE)


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_item(item_id):
    """Retrieves a specific item from the data store by ID."""
    item = next((item for item in DATA_STORE if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    else:
        return Response("Item not found", status=404, mimetype='text/html')


@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def add_item(item_id, name):
    """Adds a new item to the data store."""
    global DATA_STORE  # Access the global DATA_STORE
    new_id = DATA_STORE[-1]['id'] + 1 if DATA_STORE else 1
    new_item = {
        "id": new_id,
        "name": name,
        "done": False
    }
    DATA_STORE.append(new_item)
    return jsonify(DATA_STORE)



@app.route('/postjson', methods=['POST'])
def post_data():
    """Handles POST requests with JSON data to add a new item."""
    if request.headers.get('Content-Type') == 'application/json':
        try:
            data = request.get_json()
            new_id = DATA_STORE[-1]['id'] + 1 if DATA_STORE else 1
            new_item = {
                "id": new_id,
                "name": data.get('name', ''),  # Use .get() with default value for safety
                "done": data.get('done', False) # Convert string "true"/"false" to boolean
            }
            DATA_STORE.append(new_item)
            return jsonify(DATA_STORE)
        except (KeyError, TypeError) as e:
            logging.error(f"Error parsing JSON data: {e}")
            return Response("Invalid JSON data", status=400, mimetype='text/html')

    elif request.headers.get('Content-Type') == 'application/x-www-form-urlencoded':
        try:
            data = request.form.to_dict() # Convert form data to a dictionary
            new_id = DATA_STORE[-1]['id'] + 1 if DATA_STORE else 1
            new_item = {
                "id": new_id,
                "name": data.get('name', ''),
                "done": data.get('done', 'False').lower() == 'true' # Handle string to boolean conversion
            }
            DATA_STORE.append(new_item)
            return jsonify(DATA_STORE)
        except (KeyError, ValueError) as e:
            logging.error(f"Error parsing form data: {e}")
            return Response("Invalid form data", status=400, mimetype='text/html')

    else:
        return Response("Unsupported Content-Type", status=415, mimetype='text/html')



@app.route('/postjson', methods=['GET'])
def get_post_json():
    """Returns the entire data store as JSON (GET request for /postjson)."""
    return jsonify(DATA_STORE)



if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0')

